// Promotes reviewed sprites from the sandbox API to the real API
// (ARCHITECTURE.md 6.4). Usage, from the repo root:
//
//   make promote-sprites IDS="STONE_WALL,GRASS"            dry run, writes nothing
//   make promote-sprites IDS="STONE_WALL,GRASS" APPLY=1    backs up, then writes
//
// Each sprite is matched by its user-facing `id`, because `_id` is generated by
// the server and can't be carried over: no sprite with that `id` in the real
// database means create, one means replace it. It is a client of the two APIs
// and never connects to MongoDB itself. Sprites reference nothing, so no ids
// need translating (that is [Skills 6]).
//
// Run through tsx (like the MCP): the schema file is imported as it is.
import { spriteSchema } from '../frontend/src/schemas/spriteSchema'

const SANDBOX_URL = process.env.SANDBOX_API_URL ?? 'http://localhost:8081'
const REAL_URL = process.env.REAL_API_URL ?? 'http://localhost:8080'

type Sprite = ReturnType<typeof spriteSchema.parse>
type Stored = Record<string, unknown> & { _id: string }

type Step =
	| { id: string; action: 'create'; sprite: Sprite }
	| {
			id: string
			action: 'update'
			_id: string
			sprite: Sprite
			changes: string
	  }
	| { id: string; action: 'unchanged' }

const args = process.argv.slice(2)
const apply = args.includes('--apply')
const ids = [
	...new Set(
		args
			.filter((a) => a !== '--apply')
			.flatMap((a) => a.split(','))
			.map((a) => a.trim())
			.filter(Boolean),
	),
]

const stop = (lines: string[]): never => {
	for (const line of lines) console.error(line)
	process.exit(1)
}

async function call(base: string, path: string, init: RequestInit = {}) {
	const res = await fetch(`${base}${path}`, {
		...init,
		headers: { 'Content-Type': 'application/json' },
	})
	if (!res.ok) {
		throw new Error(
			`${init.method ?? 'GET'} ${base}${path} failed: ${res.status} ${await res.text()}`,
		)
	}
	return res
}

// Equality filter on `id`; the API returns a plain array.
const findById = async (base: string, id: string) =>
	(await (
		await call(base, `/collection/sprites?id=${encodeURIComponent(id)}`)
	).json()) as Stored[]

const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)

// What differs between the sandbox's sprite and the real one, in words.
function describeChanges(next: Sprite, current: Stored) {
	const changes: string[] = []
	if (!same(next.name, current.name)) changes.push('name')
	if (!same(next.category, current.category)) changes.push('category')
	if (!same(next.background, current.background)) changes.push('background')
	if (!same(next.pixels, current.pixels)) {
		const was = Array.isArray(current.pixels) ? current.pixels : []
		const n = next.pixels.filter((p, i) => p !== (was[i] ?? undefined)).length
		changes.push(`${n} pixels differ`)
	}
	return changes
}

async function plan(): Promise<Step[]> {
	const steps: Step[] = []
	const problems: string[] = []

	for (const id of ids) {
		const fromSandbox = await findById(SANDBOX_URL, id)
		if (fromSandbox.length !== 1) {
			problems.push(
				fromSandbox.length === 0
					? `${id}: not found in the sandbox`
					: `${id}: ${fromSandbox.length} sandbox sprites have this id`,
			)
			continue
		}
		const parsed = spriteSchema.safeParse(fromSandbox[0])
		if (!parsed.success) {
			problems.push(
				`${id}: invalid in the sandbox: ` +
					parsed.error.issues
						.map((i) => `${i.path.join('.') || '(sprite)'} ${i.message}`)
						.join('; '),
			)
			continue
		}

		const inReal = await findById(REAL_URL, id)
		if (inReal.length > 1) {
			problems.push(`${id}: ${inReal.length} real sprites have this id`)
		} else if (inReal.length === 0) {
			steps.push({ id, action: 'create', sprite: parsed.data })
		} else {
			const changes = describeChanges(parsed.data, inReal[0])
			steps.push(
				changes.length === 0
					? { id, action: 'unchanged' }
					: {
							id,
							action: 'update',
							_id: inReal[0]._id,
							sprite: parsed.data,
							changes: changes.join(', '),
						},
			)
		}
	}

	if (problems.length > 0) {
		stop([
			'Nothing was written. Fix these first:',
			...problems.map((p) => `  ${p}`),
		])
	}
	return steps
}

async function main() {
	if (ids.length === 0)
		stop(['Give at least one sprite id: IDS="STONE_WALL,GRASS"'])
	if (new URL(SANDBOX_URL).origin === new URL(REAL_URL).origin) {
		stop([
			`The sandbox and real API are the same address (${REAL_URL}). Refusing.`,
		])
	}

	console.log(`Promote sprites: sandbox ${SANDBOX_URL} -> real ${REAL_URL}`)
	const steps = await plan()
	for (const s of steps) {
		const label = {
			create: 'CREATE',
			update: 'UPDATE',
			unchanged: 'unchanged',
		}[s.action]
		console.log(
			`  ${label.padEnd(9)} ${s.id}${s.action === 'update' ? `  (${s.changes})` : ''}`,
		)
	}

	if (!apply) {
		console.log('Dry run: nothing was written.')
		return
	}

	let written = 0
	for (const s of steps) {
		if (s.action === 'unchanged') continue
		try {
			const res =
				s.action === 'create'
					? await call(REAL_URL, '/collection/sprites', {
							method: 'POST',
							body: JSON.stringify(s.sprite),
						})
					: await call(REAL_URL, `/collection/sprites/${s._id}`, {
							method: 'PUT',
							body: JSON.stringify(s.sprite),
						})
			const stored = (await res.json()) as Stored
			written += 1
			console.log(`  done      ${s.id} (${s.action}d, _id ${stored._id})`)
		} catch (e) {
			// Safe to re-run: sprites already written show up as unchanged.
			stop([
				`Stopped at ${s.id} after ${written} written: ${(e as Error).message}`,
			])
		}
	}
	console.log(`Wrote ${written} sprite(s).`)
}

main().catch((e) => stop([(e as Error).message]))
